      \end{sloppypar}
  \end{cjenum}

\label{lem:exposing}\index{lemma@Lemma!Exposing}
  A rule exposes an edge only in the following cases:
 \begin{djenum}

  \item\label{i:lem.exposing.doom}
    Member cell whose neighbor is doomed, and dies at \( \ensuremath{\mathord{\textsf{\slshape{Age\/}}}}=0 \), that is at a cut,
    as in Definition~\ref{def:cut}.

  \item\label{i:lem.exposing.channel}
   Channel cell, \( \ensuremath{\mathord{\textsf{\slshape{Age\/}}}}=\ensuremath{\mathinner{\textsf{\upshape{compute-start}}}} \).

  \item\label{i:lem.exposing.grow-end}
    Germ cell or growth, non-end-cell. \( \ensuremath{\mathord{\textsf{\slshape{Age\/}}}}=\ensuremath{\mathinner{\textsf{\upshape{grow-end}}}} \), or when
    a germ cell is killed by \( \ensuremath{\mathord{\texttt{\slshape{Adapt\/}}}} \) invoked in \( \ensuremath{\mathord{\texttt{\slshape{Germ-grow\/}}}}.\ensuremath{\mathord{\texttt{\slshape{passive\/}}}} \).

 \end{djenum}

\label{lem:parent}\index{lemma@Lemma!Parent}
   Suppose that \( I_{1}(x) \) is damage-free during \( (u-T^{\bullet},u] \)
   (that is \( x \) is not affected via neighbors during this time,
   as in Definition~\ref{def:affecting}),
   and the non-germ cell \( x \) becomes animated at time \( u \).
   Then there is a \( j\in\{-1,1\} \) and \( t'\in(u-3T^{\bullet},u-{T_{\bullet}}/2] \) such that
the following holds:

  \begin{cjenum}

   \item\label{i:parent.gen}
\( x \) gets animated by
parent \( x+j{B}  \), whose state at that time makes it a sibling of \( (x,u) \).

\item\label{i:parent.sib}
If \( I_{0}(x)\cup I_{0}(x+j{B} ) \) remains damage-free during \( (u,u+T^{\bullet}] \) then
\( x \) and \( x+j{B}  \) remain siblings during that time.

\end{cjenum}

\label{def:traceable}
 A cell $(x,t)$ will be called \emph{traceable} if $I_{0}(x)$ is damage-free
during $(t-4\ensuremath{\mathinner{\textsf{\upshape{purge-t}}}},t]$.

\label{def:age-lag}
Let $P=\mathopen( c_{0},\dots,c_{n}\mathclose)$ be a forward path.
The \emph{age progress} of  $P$ is defined as
 \begin{align*}
   \ensuremath{\mathord{\textit{age-progress\/}}}(P) = \sum_{i=0}^{n-1}(\ensuremath{\mathord{\textsf{\slshape{Age\/}}}}(c_{i+1})-\ensuremath{\mathord{\textsf{\slshape{Age\/}}}}(c_{i}) \mskip-\medmuskip\mkern5mu\mathbin
  {\operator@font amod}\penalty900
  \mkern5mu\mskip-\medmuskip {U} ).
 \end{align*}

\label{def:boundary-path}
Let us call the sibling relation between two cells
\emph{strong}\index{sibling!strong},
if either they have been siblings for at least \( 2T^{\bullet} \) time units
or one cell is a parent of the other.

A cell is called for example a \emph{weak left exposed edge}\index{edge!exposed!weak}
if it is either a left exposed edge or
would be one in case it had no left sibling, and has no strong left sibling.
A sequence \( R_{1}=(y_{0},v_{0}),\dots, (y_{m},v_{m}) \) of cell-time pairs
with \( v_{0}<v_{1}<\dots<v_{m} \) will be called a \emph{left boundary path}\index{path!boundary}
if \( y_{i} \) is a weak left exposed edge during \( (v_{i},v_{i+1}) \) and one of the following is true:
      \begin{djenum}
        \item Cell \( y_{i-1}=y_{i}-{B}  \) dies at time \( t_{i} \) and is a strong sibling of
\( y_{i} \) at time \( t_{i}- \).
        \item Cell \( y_{i}=y_{i-1}-{B}  \) is created at time \( t_{i} \) by parent \( y_{i-1} \).
      \end{djenum}

\label{lem:bad-gap-infr}
 \index{lemma@Lemma!Bad Gap Inference}
  Let \( c_{0}=(x_{0},t_{0}) \) be a left exposed edge,
 \begin{align*}
    D &= \left[x_{0}-(\ensuremath{\mathinner{\textsf{\upshape{split-n}}}}+1.1){B} ,x_{0}+(\ensuremath{\mathinner{\textsf{\upshape{heal-span}}}}+1.1) {B} \right),
\\  I &= (t_{0}-\ensuremath{\mathinner{\textsf{\upshape{split-t}}}},t_{0}].
 \end{align*}
Assume \( D\times I \) is damage-free.
  Then one of the following holds:
  \begin{djenum}

  \item\label{i:bad-gap-infr.gap}
 There is a bad gap on the left of \( c_{0} \);

\item\label{i:bad-gap-infr.exposing}
  There is a boundary path of length \( <\ensuremath{\mathinner{\textsf{\upshape{split-n}}}} \) leading backwards in time from \( c_{0} \)
to a cell undergoing one of the changes listed in Lemma~\ref{lem:exposing}
(Exposing).

   \end{djenum}
  The same statement holds if we replace left with right.

\label{lem:cover}
Let $c_{0}=(x_{0},t_{0})$ be a live cell belonging to colony $\mathcal{C}$ with
starting cell $z$,  
\begin{align*}
     I &=\left[z-({Q} +1.1){B} ,z+(2{Q} +1.1){B} \right).
\end{align*}
For \( J \) as in~\eqref{eq:J-K} let
\begin{align*}
n_{J}&=2|J|/p_{1}{T_{\bullet}}+3\Delta 
\end{align*}
 and assume that \( \ensuremath{\mathord{\textit{Damage\/}}}^{*} \) does not intersect \( I\times J \).
Consider a trace-back path $P_{1}$ in $I\times J$ leading backwards from $c_{0}$
to a cell $c_{1}=(x_{1},t_{1})$.
The following holds.
\begin{cjenum}

\item\label{i:cover.stays}
  If $c_{0}$ is not an outer or germ cell younger than
$\ensuremath{\mathinner{\textsf{\upshape{grow-end}}}}+n_{J}$ then the path $P_{1}$ does not leave its own colony.

\item\label{i:cover.xposed}
Assume $t_{1}\le t_{0}-\ensuremath{\mathinner{\textsf{\upshape{destr-t}}}}{Q}$, the rectangle
 \begin{align*}
    I \times(t_{1}-\ensuremath{\mathinner{\textsf{\upshape{split-t}}}},t_{1}+\ensuremath{\mathinner{\textsf{\upshape{split-t}}}}]
 \end{align*}
 is damage-free, \( c_{1} \) is not a doomed member cell with  \( |\ensuremath{\mathord{\textsf{\slshape{Age\/}}}}(c_{1}) > {U}-2{Q}-\ensuremath{\mathinner{\textsf{\upshape{split-n}}}} \).
Then the maximal domain containing the cell $c_{1}$  contains the colony of \( c_{0} \) as
 well as its originating colony.





\end{cjenum}

\label{lem:attrib}
Assume that the live cell $c_{0}=(x_{0},t_{0})$ is traceable, and is not a
germ cell younger than $\ensuremath{\mathinner{\textsf{\upshape{grow-end}}}}+2|J|/p_{1}{T_{\bullet}}$.                              
Then we have:
  \begin{cjenum}

  \item\label{lem:attrib.expan}
  $c_{0}$ can be attributed to its originating colony.

\item\label{lem:attrib.no-expan}
  If it is a member cell, or an outer or germ cell older than $\ensuremath{\mathinner{\textsf{\upshape{grow-end}}}} + |J|/p_{1}{T_{\bullet}}$
  then it can also be attributed to its own colony.
   \end{cjenum}

\label{crl:progress}
  Under the assumptions of Lemma~\ref{lem:colony-trace-back}, suppose that
  the age progress along the path is \( n \).
  Then
  \begin{align*}
   (n-\Delta -3){p}_{1}{T_{\bullet}} \le t_{1}-t_{0} \le 4(n+6{Q}){p}_{1}T^{\bullet}.
\end{align*}

\label{def:encoding}
The encoding 
 \begin{align*}
  \varphi_{*}:{\mathbb{S}}_{k+1}\to{\mathbb{S}}_{k}^{{Q} _{k}}
 \end{align*}
takes the state of a cell, applies to it the 
error-correcting code $\alpha_{*}$ introduced above in
Definition~\ref{def:the-err-corr-code} and
copies the result to the $\ensuremath{\mathord{\textsf{\slshape{Info\/}}}}$ track of a colony.
The other parts of the colony are set in such a way as they are to be
found at the beginning of a work period.

\label{lem:legality}
  Assume that, for some number \( a \), the set \( \ensuremath{\mathord{\textit{Damage\/}}}^{*} \) does not
intersect \( \left[x,x+{Q} {B} \right)\times(a-2T^{\bullet *},a+2T^{\bullet *}] \), 

further that \( \sigma_{1},\sigma_{2} \),
as in Definition~\ref{def:special-sw-times} (Special switching times)
are defined for cell \( x \) of medium \( M^{*} \) in the interval \( (a-2T^{\bullet *},a+2T^{\bullet *}] \),
using Definition~\ref{def:decoding} (Decoding).
Then the following holds, using Definition~\ref{def:legal} (Legality):
\begin{cjenum}
  \item\label{i:legality.legal}
    \( \ensuremath{\mathord{\textit{legal\/}}}_{k+1}(\eta^{*}(x, \sigma_{2}-), \eta^{*}(x, \sigma_{2})) = 1 \), thus
    proving Condition~\ref{cond:comput}\ref{i:comput.legal-comp}.
  \item\label{i:legality.time-bounds}
    \( T_{\bullet}^{*} \le \sigma_{2} - \sigma_{1} \le T^{\bullet *} \), thus proving
    Condition~\ref{cond:comput}\ref{i:comput.dwell-pd-bd}.

    \begin{sloppypar}
\item\label{i:legality.rand} The randomization property
  \( g(\alpha(\ensuremath{\mathord{\textit{rand\/}}}),j, W_{0}(x,a),\eta^{*}) \), as defined
  in Condition~\ref{cond:comput}\ref{i:comput.rand}
  will hold: it can be expressed in the needed canonical simulation of
  Definition~\ref{def:canon-simul}.      
    \end{sloppypar}
\end{cjenum}

\label{lem:growth}\index{lemma@Lemma!Growth}
  For a trajectory \( \eta \), Condition~\ref{cond:comput}\ref{i:comput.creation}
  holds for the decoded trajectory \( \eta^{*} \).

For an interval \( I=\left[a,b\right) \) we define its \( d \)-neighborhood as 
 \gloprocg.greek.cap@$\Gamma(I, d)$.))) 
 \begin{equation}\label{eq:Gg-interval}
  \Gamma(I, d)=(a-d,b+d].
 \end{equation}
 We will also write $\Gamma(x,d)=(x-d,x+d]$.

\label{lem:lasting-control}
  Let \( t_{1}<t_{2} \) be times.
  Assume that interval \( K=\left[x_{0},x_{0}+{B}\right) \)
  is controlled at time \( t_{1} \), and
\begin{align*}
 \Gamma(K, 3{B})\times(t_{1} - ({p}_{0}+2)T^{\bullet},t_{2}]  
\end{align*}
is damage-free.
  Then \( K \) is controlled at time \( t_{2} \).

\label{lem:arising-control}
   \( K=\left[x_{0},x_{0}+{B}\right) \) be a space interval and \( t_{1},t_{2} \)
   times with \( t_{2}=t_{0}+d{p}_{0}T^{\bullet} \),  where
   \begin{align}\label{eq:d-bound}
 d < {p}_{1}/\lambda{p}_{0} .
\end{align}
   Assume that
\( \Gamma(K, (d+1){B})\times(t_{1} - 3T^{\bullet},t_{2}] \) is damage-free, and
the body of a cell \( x_{1} \) intersects \( \Gamma(K,d{B}) \) at time \( t_{1} \).
  Then \( K \) is controlled at time \( t_{2} \).

\label{def:germ-level}
  In a trajectory \( \eta \) of a medium \( M \), we will say that a space interval
  at time \( t \) is \emph{germ-level}, if it has no colony cells.

\label{lem:germ-unexposed}
    \begin{sloppypar}
    In a trajectory \( \eta \), let \( c_{1}=(x_{1},t_{1}) \) be a germ cell with
\( \ensuremath{\mathord{\textsf{\slshape{G-size\/}}}} = L \) and \( \ensuremath{\mathord{\textsf{\slshape{Age\/}}}}>3R L \).
Assume that at time \( t_{1} \), with a germ cell body \( K=\left[x_{1},x_{1}+2{B}^{*}\right) \),
the space-time rectangle
  \begin{align}\label{eq:large-rect}
    \Gamma(K, 25{B}^{*}) \times \Gamma(t_{1}, T^{\bullet *}).
  \end{align}
is free of damage, and the domain containing \( c_{1} \) has an exposed edge.
Then there is an \( L' \) with \( \rho L< L'\le 5{Q} \) such that in 
\begin{align}\label{eq:germ-unexposed-area}
  \Gamma(x_{1}, 5 L' {B})
  \times\left[t_{1},t_{1}+5R L'\tau_{2}\right)
\end{align}
there is a colony cell, or a germ cell with
\( \ensuremath{\mathord{\textsf{\slshape{G-size\/}}}}\ge L' \), or one with \( \ensuremath{\mathord{\textsf{\slshape{Addr\/}}}}=e'_{j} \) for \( j=\pm 1 \)
(recall~\eqref{eq:e'_j}).
  \end{sloppypar}

\label{lem:birth}
  Consider a trajectory \( \eta \) of \( M_{k} \),
  with a germ cell \( c_{1}=(x_{1},t_{1}) \), \( K=\left[x_{1},x_{1}+2{B}^{*}\right) \),
  and assume that the large space-time rectangle~\eqref{eq:large-rect}
  is free of damage.
  The probability that the rectangle contains no colony cell is bounded by \( \theta_{k} \).
  Moreover, there is a canonical simulation in the sense of Definition~\ref{def:canon-simul}
 providing this estimate.

\label{df:qualif-control}
Let us define the constants
\begin{align}\label{eq:C_1,C_2}
   C_{1}=(26{p}_{0}+2)\lambda, \quad C_{2}=26{p}_{0}+2.
\end{align}
  Let ``blue'' be some color.
  For some parameter $\sigma>0$, let \( \mathcal{E} \) be an event derived
  from the behavior of trajectory \( \eta \) of medium \( M \) before time \( t \).
  We will say that trajectory $\eta$ is \emph{germ-level blue}
  \emph{modulo} \( (\sigma,\mathcal{E}) \) at time \( t \) on the finite or infinite interval \( H \) if
for every set of space intervals $I_{1},\dots,I_{n}\subset H$,
of size \( C_{1}{B} \), at distance \( \ge 2 C_{1}{B} \)
from each other, the probability that \( \neg\mathcal{E} \) holds and
none of the \( I_{j} \) is germ-level and blue is at most $\sigma^{n}$.
When \( H \) is the whole space then we will have \( \mathcal{E}=\emptyset \), so
the ``modulo \( \mathcal{E} \)'' qualification can be omitted.

For an amplifier, the parameter \( \theta_{k} \) was
defined in~\eqref{eq:no-birth-prob}.
Let 
\begin{equation}\label{eq:sg}
    \sigma_{k} =
                    \begin{cases}
                      \theta_{1} &\text{ if } k=1,
                      \\ 2\theta_{k-1}&\text{ if }k>1.
                    \end{cases}
 \end{equation}
As usual, for level \( k \) we will simply write \( \sigma=\sigma_{k} \), 
\( \sigma^{*}=\sigma_{k+1} \), and so on.
